from lessonkit import mk,qs
E=dict(cls=4,subj="evs",subj_file="evs")
mk(E,"living-together","communities-and-helping-each-other","Communities and helping each other","சமூகங்களும் ஒருவருக்கொருவர் உதவுதலும்",["Say what a community is","Give examples of helping each other"],
 ("The flooded street","After heavy rain the street near Anu's school was full of water. Neighbours brought boats made of tubs, shared food and helped the old.\n\"We live better when we help each other,\" said Anu."),
 ["A community is a group of people who live or work together. A village, a street, a school and a town are communities. People in a community depend on each other: farmers grow food, teachers teach, doctors treat and drivers carry us.","We follow rules in a community so that everyone is safe: keep places clean, share, wait for our turn and respect elders. When there is trouble, such as a flood, neighbours help each other.","Living together means being kind, listening to others and respecting differences in language, food and festivals."],
 ["community","neighbour","rules","respect"],
 [("A community is a group of people who live or work together.","community"),("People depend on each other: farmers, teachers, doctors.","helpers"),("We follow rules so that everyone is safe.","rules"),("In trouble, neighbours help each other.","helping")],
 ("How does a school community work together?",[("Teachers teach and children learn.","Roles."),("Cleaners and gardeners keep the school neat.","More helpers."),("Everyone follows rules, so the school runs well.","Rules.")]),
 ("A friend says he does not need anyone else. How will you reply?",["We depend on farmers, doctors and teachers.","Communities work together."],["Thinking we live alone."]),
 ["A community is people living or working together.","We depend on and help each other.","Rules and respect keep us safe."],
 qs("a",[("m","A village is an example of a","community","machine","planet","People live together."),("t","People in a community depend on each other.",True,"Yes."),("m","A doctor","treats the sick","grows rice","drives buses","Health helper."),("t","Rules in a community keep everyone safe.",True,"Yes."),("m","In a flood neighbours","help each other","stay away","ignore","Help."),("s","Name one community helper. Write one word.",["farmer","doctor","teacher","driver","nurse","policeman","postman","tailor"],"Many helpers."),("m","Living together needs","respect","anger","fear","Respect."),("t","We must respect differences in food and language.",True,"Yes.")]))
mk(E,"exploring-our-neighbourhood","places-people-and-maps","Places, people and maps","இடங்கள், மனிதர்கள், வரைபடங்கள்",["Name places in a neighbourhood","Read a simple map"],
 ("The neighbourhood walk","Ravi's class went for a walk around the school: a post office, a temple, a bank, a park, a bus stop and a small shop.\nBack in class they drew a map of the walk."),
 ["Our neighbourhood is the area around our home or school. It has places such as a school, shop, hospital, park, post office, bank and bus stop. It also has people who work there, such as the shopkeeper, nurse, postman and bus driver.","A map is a drawing of a place seen from above. It uses symbols and a key to show what each symbol means. A map also tells directions: north, south, east and west.","To make a map of our neighbourhood, walk around, note places, draw them in order and add a key and directions."],
 ["neighbourhood","map","symbol","key","direction"],
 [("The neighbourhood is the area around our home.","neighbourhood"),("It has shops, hospitals, parks and the people who work there.","places and people"),("A map is a drawing of a place from above.","map"),("A key tells what each symbol means.","key")],
 ("What do we need to make a map of our street?",[("Walk around and note the places.","Observe."),("Draw each place with a symbol.","Symbols."),("Add a key and the directions.","Key and directions.")]),
 ("A friend says a map and a photo are the same. How will you reply?",["A map shows a place from above with symbols.","A photo shows how it looks."],["Mixing maps and photos."]),
 ["The neighbourhood has places and people.","A map shows a place from above.","A key explains symbols."],
 qs("n",[("m","A map shows a place from","above","inside","the ground only","Top view."),("t","A key explains the symbols on a map.",True,"Yes."),("m","The area around our home is our","neighbourhood","kitchen","country","Nearby."),("t","A postman works at a hospital.",False,"At the post office."),("m","Which is a direction?","north","blue","big","North."),("s","Name one place in a neighbourhood. Write one word.",["school","shop","hospital","park","post office","bank","temple","bus stop","market"],"Many places."),("m","Map symbols are explained in the","key","title","border","Key."),("t","We should draw places in order on a map.",True,"Yes.")]))
mk(E,"nature-trail","observing-plants-and-animals","Observing plants and animals","தாவரங்களையும் விலங்குகளையும் கவனித்தல்",["Observe nature carefully","Name the parts of a habitat"],
 ("The trail in the park","In a park the children followed a nature trail. They saw an ant carrying a crumb, a spider's web, a banyan tree and a squirrel.\n\"Look but do not disturb,\" said the teacher."),
 ["A nature trail is a walk where we watch plants, animals and their homes. We can use our senses: look, listen and smell. We should not pluck flowers or harm animals.","The place where a plant or animal lives is its habitat. A bird lives in a nest on a tree, a fish lives in water and an ant lives in an anthill. Habitats give food, water and shelter.","We can keep a notebook, draw what we see and compare leaves, insects and birds. Every living thing has a role."],
 ["nature trail","habitat","observe"],
 [("A nature trail is a walk to watch plants and animals.","nature trail"),("Look and listen but do not disturb.","observe carefully"),("A habitat is the home of a plant or animal.","habitat"),("Habitats give food, water and shelter.","needs")],
 ("Name the habitat of a fish and a bird.",[("A fish lives in water.","Water habitat."),("A bird lives in a nest on a tree.","Tree habitat."),("Each habitat gives what the animal needs.","Food, water, shelter.")]),
 ("A friend wants to pluck flowers on the trail. What do you say?",["Look but do not harm.","Other people and insects enjoy them too."],["Harming nature."]),
 ["A nature trail is a walk to observe nature.","A habitat is a living thing's home.","Do not harm plants and animals."],
 qs("t",[("m","The home of an animal is its","habitat","school","market","Habitat."),("t","We should pluck flowers on a nature trail.",False,"We should not."),("m","A fish lives in","water","a nest","an anthill","Water."),("t","An ant lives in an anthill.",True,"Yes."),("m","On a trail we use our","senses","phones only","toys","Observe."),("s","Where does a bird make its nest? Write one word.",["tree","trees"],"On a tree."),("m","Habitats give","food, water and shelter","only toys","only noise","Needs."),("t","We can draw what we see.",True,"Yes.")]))
mk(E,"growing-up-with-nature","life-cycles-of-plants-and-animals","Life cycles of plants and animals","தாவரங்கள், விலங்குகளின் வாழ்க்கைச் சுழற்சி",["Describe a plant's life cycle","Describe the life of a butterfly"],
 ("The bean seed","Meera planted a bean seed in a pot. In a few days a tiny shoot came up and soon it had leaves and flowers.\n\"The seed became a plant,\" she wrote, \"and the plant makes seeds again.\""),
 ["Plants grow from seeds. A seed sprouts when it gets water, warmth and air. It grows into a plant with roots, stem and leaves. The plant flowers, the flowers make fruits and the fruits have new seeds. This is the plant life cycle.","A butterfly begins as an egg. A caterpillar comes out and eats leaves. It becomes a pupa and then a butterfly. A frog begins as an egg, becomes a tadpole and then grows into a frog.","All living things are born, grow, make young ones and die. We too grow from babies to children to adults."],
 ["seed","sprout","caterpillar","life cycle"],
 [("A seed needs water, warmth and air to sprout.","seed"),("A plant flowers and makes fruits with new seeds.","plant cycle"),("A butterfly goes through egg, caterpillar, pupa, butterfly.","butterfly"),("A frog goes through egg, tadpole, frog.","frog")],
 ("Put these in order: butterfly, egg, pupa, caterpillar.",[("First the egg.","Start."),("Then the caterpillar and the pupa.","Middle."),("At last the butterfly.","End.")]),
 ("A friend says a caterpillar is a different animal from a butterfly. How will you reply?",["The caterpillar grows into a butterfly.","They are stages of one life."],["Seeing stages as separate animals."]),
 ["A seed grows into a plant that makes new seeds.","A butterfly has four stages.","All living things grow and make young ones."],
 qs("l",[("m","A seed needs to sprout","water, warmth and air","only sand","stones","Basics."),("t","A caterpillar becomes a butterfly.",True,"Yes."),("m","A frog begins as an","egg","adult","pupa","Egg."),("t","A tadpole comes before a frog.",True,"Yes."),("m","The stage after the caterpillar is the","pupa","egg","seed","Pupa."),("s","What does a flower make that has seeds? Write one word.",["fruit","fruits"],"Fruit."),("m","A plant has","roots, stem and leaves","only wings","only fins","Parts."),("t","Living things never grow.",False,"They grow.")]))
mk(E,"food-for-health","food-groups-and-balanced-diet","Food groups and a balanced diet","உணவுக் குழுக்களும் சமச்சீர் உணவும்",["Name the food groups","Plan a balanced meal"],
 ("The tiffin box","Asha's tiffin had only chips. Her teacher said, \"Chips taste nice but our body needs many kinds of food.\"\nNext day Asha brought idli, sambar, a banana and some curd."),
 ["Food gives us energy to work and play, helps us grow and protects us from illness. Foods can be grouped. Cereals like rice, wheat and ragi give energy. Pulses, milk, eggs and fish help us grow. Fruits and vegetables give vitamins and minerals that protect us. Oil and sugar give extra energy in small amounts.","A balanced diet has food from all groups in the right amounts. Drinking enough water and eating fruits and vegetables help us. We should eat less of oily and sugary foods.","Food must be fresh and clean. Wash hands before eating and wash fruits and vegetables."],
 ["cereal","pulse","vitamin","balanced diet"],
 [("Cereals like rice and ragi give energy.","cereals"),("Pulses, milk and eggs help us grow.","body-building food"),("Fruits and vegetables protect us.","protective food"),("A balanced diet has all groups.","balanced diet")],
 ("Is a meal of rice, dal, vegetables and curd balanced?",[("Rice gives energy.","Cereal."),("Dal and curd help us grow; vegetables protect us.","Pulses, milk, vegetables."),("So the meal is balanced.","All groups present.")]),
 ("A friend says chips alone are a good meal. How will you reply?",["Chips lack many things we need.","A balanced diet needs all groups."],["Eating one kind of food."]),
 ["Foods give energy, help growth and protect.","A balanced diet has all groups.","Keep food clean and fresh."],
 qs("f",[("m","Rice and wheat are","cereals","pulses","fruits","Cereals."),("t","Fruits and vegetables protect us.",True,"Yes."),("m","Milk and eggs help us","grow","sleep only","fly","Body-building."),("t","A balanced diet means eating only sweets.",False,"All groups."),("m","We should wash hands","before eating","never","only on Sundays","Hygiene."),("s","Name one fruit. Write one word.",["mango","banana","apple","orange","guava","papaya","grapes","jackfruit"],"Many."),("m","Ragi is a","cereal","metal","toy","A grain."),("t","Drinking water is good for us.",True,"Yes.")]))
mk(E,"happy-and-healthy-living","hygiene-exercise-and-feelings","Hygiene, exercise and feelings","சுகாதாரம், உடற்பயிற்சி, உணர்வுகள்",["Say good habits for health","Name and handle feelings"],
 ("Raju's morning","Raju woke early, brushed his teeth, bathed, ate breakfast and played for an hour. He slept early.\n\"I feel fresh and happy,\" he said."),
 ["To stay healthy keep your body clean: bathe daily, brush teeth twice, wash hands before eating and after using the toilet, and cut nails. Wear clean clothes. Keep the surroundings clean.","Play and exercise to keep the body strong. Sleep for enough hours so that the body rests: children need about 9 to 10 hours. Eat on time and drink clean water.","We also have feelings: happy, sad, angry, afraid. It is all right to have them. We can talk to someone we trust, take deep breaths and do something calming when upset."],
 ["hygiene","exercise","feeling"],
 [("Bathe daily, brush twice and wash hands.","hygiene"),("Exercise and sleep keep the body strong.","exercise and sleep"),("All feelings are natural.","feelings"),("Talk to someone you trust when upset.","talk")],
 ("When should we wash our hands?",[("Before eating food.","First."),("After using the toilet.","Second."),("After playing outside.","Third.")]),
 ("A friend says it is wrong to feel sad. How will you reply?",["Everyone feels sad sometimes.","We can talk and feel better."],["Hiding feelings."]),
 ["Keep clean and exercise.","Sleep and eat on time.","Talk about your feelings."],
 qs("h",[("m","We brush our teeth","twice a day","never","once a year","Twice."),("t","We wash hands before eating.",True,"Yes."),("m","Children need about","9 to 10 hours of sleep","2 hours of sleep","20 hours of sleep","About 9-10."),("t","It is wrong to feel sad.",False,"It is natural."),("m","When upset we can","talk to someone we trust","hurt others","hide forever","Talk."),("s","How many times a day should we brush? Write only the number.",["2","two"],"Twice."),("m","Exercise makes the body","strong","weak","sleepy only","Strong."),("t","Clean surroundings help health.",True,"Yes.")]))
mk(E,"how-things-work","simple-machines","Simple machines","எளிய இயந்திரங்கள்",["Name simple machines","Say how they make work easier"],
 ("The seesaw","In the park Anu and her brother played on a seesaw. Anu sat near the end and her heavier father sat near the middle.\n\"Lifting is easier with a lever,\" said her father."),
 ["Simple machines make our work easier. A lever is a bar that turns on a point, the fulcrum. A seesaw, a crowbar and scissors use levers. A wheel and axle helps things to move, like in a cart or a bicycle.","A ramp, also called an inclined plane, makes it easier to raise things to a height. A pulley with a rope helps to lift a bucket from a well. A screw and a wedge hold or cut things.","Machines do not save work. They make it easier by changing the push or pull we need."],
 ["lever","wheel","ramp","pulley"],
 [("A lever is a bar that turns on a point.","lever"),("A wheel helps things move.","wheel"),("A ramp helps us raise things.","ramp"),("A pulley helps to lift a bucket from a well.","pulley")],
 ("Why is it easier to push a drum up a ramp than to lift it?",[("A ramp is a slope.","Inclined plane."),("We push over a longer distance with less effort.","Less force."),("So the work is easier.","Easier, not less work.")]),
 ("A friend says machines have motors only. How will you reply?",["Simple machines have no motors.","A lever, a wheel and a ramp are machines."],["Thinking all machines need electricity."]),
 ["Simple machines make work easier.","Examples: lever, wheel, ramp, pulley.","They change the push or pull needed."],
 qs("m",[("m","A seesaw is a","lever","wheel","pulley","Lever."),("t","A pulley helps to lift a bucket from a well.",True,"Yes."),("m","A ramp helps us","raise things","cut paper","boil water","Inclined plane."),("t","Simple machines always have motors.",False,"No."),("m","Scissors use","levers","pulleys only","ramps only","Lever."),("s","Name one simple machine. Write one word.",["lever","wheel","pulley","ramp","screw","wedge"],"Many."),("m","A bicycle uses","wheels","only a ramp","only a lever","Wheel."),("t","Machines make work easier.",True,"Yes.")]))
mk(E,"how-things-are-made","from-raw-material-to-product","From raw material to product","மூலப்பொருளிலிருந்து பொருள் வரை",["Trace how something is made","Say who makes things"],
 ("The notebook","Meena asked, \"How is my notebook made?\"\nHer teacher said, \"Trees are cut, the wood is made into pulp and then into paper. The paper is cut, stitched and covered.\""),
 ["Many things are made from raw materials. Wood is the raw material of paper. Cotton is the raw material of cloth. Milk makes curd, butter and ghee. Wheat makes flour and then bread.","To make cloth: cotton is picked, cleaned, spun into thread, woven into cloth and stitched into clothes. The steps must be in the correct order.","Making things uses people, tools and often machines. We should not waste things and should reuse paper and cloth to save trees and cotton."],
 ["raw material","pulp","thread","weave"],
 [("Raw materials are what things are made from.","raw materials"),("Wood makes paper. Cotton makes cloth.","examples"),("Cloth: pick, spin, weave, stitch.","cloth steps"),("Do not waste. Reuse paper and cloth.","reuse")],
 ("List the steps to make a shirt from cotton.",[("Pick and clean the cotton.","First."),("Spin it into thread and weave it into cloth.","Second."),("Cut and stitch the cloth into a shirt.","Third.")]),
 ("A friend says paper just comes from the shop. How will you reply?",["It is made from wood pulp.","Many steps and people are involved."],["Not knowing where things come from."]),
 ["Things are made from raw materials.","The steps must be in order.","Reuse to save resources."],
 qs("k",[("m","Paper is made from","wood","stones","water only","Wood pulp."),("t","Cotton is the raw material of cloth.",True,"Yes."),("m","Wheat is ground into","flour","oil","salt","Flour."),("t","Steps of making a thing can be in any order.",False,"They are in order."),("m","Milk can be made into","curd","cloth","paper","Curd."),("s","Name a raw material. Write one word.",["wood","cotton","wheat","milk","clay","sugarcane","iron"],"Many."),("m","We should reuse paper to save","trees","rivers","roads","Trees."),("t","Spinning makes thread from cotton.",True,"Yes.")]))
mk(E,"different-lands-different-lives","life-in-different-places","Life in different places","வெவ்வேறு இடங்களில் வாழ்க்கை",["Describe life in a desert, mountain and coast","Say how people suit their homes and food to the place"],
 ("Letters from friends","Ravi had pen friends in three places. Tashi lived in the Himalayas, Hamida in the Thar desert and Jose on the sea coast.\nTheir letters told of homes, food and work that were all different."),
 ["The place where people live shapes their lives. In the cold mountains people wear woollen clothes and houses have sloping roofs for snow. In the hot desert people wear light loose clothes, houses have thick walls and water is precious. On the coast many people fish and houses are built with care for storms.","Food, clothes, houses and work suit the land and weather. Mountain people grow potatoes and keep yaks or sheep. Desert people keep camels and goats. Coastal people eat fish and coconut.","People of all lands are alike in needing food, water and shelter. We should respect different ways of living."],
 ["desert","mountain","coast","climate"],
 [("In the mountains people wear woollens and keep sloping roofs.","mountains"),("In the desert water is precious and people wear light clothes.","desert"),("On the coast many people fish.","coast"),("Respect different ways of living.","respect")],
 ("Why do desert people wear loose light clothes?",[("The desert is very hot.","Climate."),("Loose clothes let air pass and keep the body cool.","Comfort."),("So the clothes suit the weather.","Place shapes life.")]),
 ("A friend laughs at the clothes of mountain people. What do you say?",["Their clothes suit the cold.","Every way of life suits its place."],["Laughing at others."]),
 ["Place and weather shape life.","Food, clothes and homes suit the land.","Respect all ways of living."],
 qs("d",[("m","People of the cold mountains wear","woollens","only cotton","nothing","Warm."),("t","Fishing is common on the coast.",True,"Yes."),("m","Desert people keep","camels","whales","penguins","Camels."),("t","All people live exactly the same way.",False,"Different places differ."),("m","Water in the desert is","precious","plenty","useless","Scarce."),("s","Name a desert in India. Write one word.",["thar","thar desert"],"The Thar."),("m","We should","respect different ways of living","laugh","ignore","Respect."),("t","Clothes suit the weather of the place.",True,"Yes.")]))
mk(E,"our-sky","sun-moon-and-stars","The Sun, the Moon and the stars","சூரியன், நிலவு, விண்மீன்கள்",["Explain day and night","Describe the Moon's phases and the stars"],
 ("Looking up","One evening Aman lay on the terrace. The Sun had set, the Moon rose and tiny stars began to twinkle.\n\"Why is the sky different at night?\" he asked."),
 ["The Sun is a star that gives us light and heat. The Earth turns round once in about 24 hours. The part facing the Sun has day and the other part has night. The Sun seems to rise in the east and set in the west because the Earth turns.","The Moon does not make its own light; it shines by the Sun's light. Its shape seems to change over about a month. A full moon looks round, a new moon is hardly seen and between them we see a crescent. These are phases.","At night we see many stars. They look small because they are very far away. Some stars make patterns called constellations, like the Saptarishi (Big Dipper), and the Pole Star shows north."],
 ["star","rotation","phase","constellation"],
 [("The Earth turns once in about 24 hours. That gives day and night.","day and night"),("The Sun rises in the east and sets in the west.","sunrise and sunset"),("The Moon shines by the light of the Sun.","Moon"),("The Pole Star shows the north.","Pole Star")],
 ("Why do we have day and night?",[("The Earth turns on its axis.","Rotation."),("The part facing the Sun has day.","Day."),("The other part is in shade and has night.","Night.")]),
 ("A friend says the Sun goes round the Earth every day. How will you reply?",["The Earth turns once in a day.","The Sun only seems to move."],["Thinking the Sun moves."]),
 ["Earth's turning causes day and night.","The Moon shines by the Sun's light.","Stars are far-off suns."],
 qs("s",[("m","The Sun rises in the","east","west","south","East."),("t","The Moon makes its own light.",False,"It reflects the Sun."),("m","Day and night are caused by the Earth's","turning","size","colour","Rotation."),("t","The Pole Star shows north.",True,"Yes."),("m","The Earth turns once in about","24 hours","12 hours","1 week","One day."),("s","In which direction does the Sun set? Write one word.",["west"],"West."),("m","Stars look small because they are","very far away","tiny","cold","Distance."),("t","A full moon looks round.",True,"Yes.")]))
